Here's the code for `MyNode` I used in the example, as I mentioned it just stores a vector of `Transform3D`:

<details>
<summary> MyNode source </summary>

```cpp
class MyNode : public Node3D {
	GDCLASS(MyNode, Node3D);

	Vector<Transform3D> xforms;

	public:

	void set_xforms(const Vector<Transform3D> &p_xforms);
	Vector<Transform3D> get_xforms() const;

	void _set_xforms(const Array &p_xforms);
	Array _get_xforms() const;

protected:

	static void _bind_methods();
};


////////////////////////////////////////////


void MyNode::set_xforms(const Vector<Transform3D> &p_xforms) {
	if (p_xforms.size() != xforms.size()) {
		clear_subgizmo_selection();
	}
	xforms = p_xforms;
	update_gizmos();
}

Vector<Transform3D> MyNode::get_xforms() const {
	return xforms;
}

void MyNode::_set_xforms(const Array &p_xforms) {
	Vector<Transform3D> x;
	x.resize(p_xforms.size());
	for (int i = 0 ; i < x.size(); i++) {
		x.write[i] = p_xforms[i];
	}
	set_xforms(x);
}

Array MyNode::_get_xforms() const {
	Array a;
	a.resize(xforms.size());
	for (int i = 0; i < xforms.size(); i++) {
		a[i] = xforms[i];
	}
	return a;
}

void MyNode::_bind_methods() {
	ClassDB::bind_method(D_METHOD("set_xforms", "xforms"), &MyNode::_set_xforms);
	ClassDB::bind_method(D_METHOD("get_xforms"), &MyNode::_get_xforms);
	ADD_PROPERTY(PropertyInfo(Variant::ARRAY, "xforms"), "set_xforms", "get_xforms");
}
```
</details>

